// Executes original classic VMX words; test-only opaque fallbacks expose stale CR6 on the baseline.
import java.nio.file.*;
import java.nio.*;
import java.math.BigInteger;
import java.util.*;
import ghidra.app.script.GhidraScript;
import ghidra.app.cmd.disassemble.DisassembleCommand;
import ghidra.app.emulator.EmulatorHelper;
import ghidra.program.model.address.AddressSet;
import ghidra.program.model.pcode.PcodeOp;
@SuppressWarnings("removal")
public class TestXenonClassicVmxNative extends GhidraScript {
 record Fixture(String name,int selector,int d,int a,int b,boolean dot){}
 int callbacks;void require(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 byte[] vb(BigInteger v){byte[] b=new byte[16],raw=v.toByteArray();System.arraycopy(raw,Math.max(0,raw.length-16),b,Math.max(0,16-raw.length),Math.min(16,raw.length));return b;}
 byte[] operation(String kind,byte[] a,byte[] b){byte[] out=new byte[16];if(kind.equals("and")){for(int i=0;i<16;i++)out[i]=(byte)(a[i]&b[i]);}else for(int i=0;i<4;i++){int x=ByteBuffer.wrap(a,i*4,4).getInt(),y=ByteBuffer.wrap(b,i*4,4).getInt();ByteBuffer.wrap(out,i*4,4).putInt(kind.equals("shift")?x>>>(y&31):x==y?-1:0);}return out;}
 void baselineFallbacks(EmulatorHelper e){for(String name:new String[]{"vectorLogicalAnd","vectorShiftRightWord","vectorCompareEqualToUnsignedWord"})e.registerCallOtherCallback(name,new ghidra.pcode.emulate.BreakCallBack(){public boolean pcodeCallback(ghidra.pcode.pcoderaw.PcodeOpRaw op){var m=emulate.getMemoryState();String kind=name.equals("vectorLogicalAnd")?"and":name.equals("vectorShiftRightWord")?"shift":"compare";m.setValue(op.getOutput(),new BigInteger(1,operation(kind,vb(m.getBigInteger(op.getInput(1),false)),vb(m.getBigInteger(op.getInput(2),false)))));callbacks++;return true;}});}
 public void run()throws Exception{Path out=Path.of(getScriptArgs()[0]);Files.createDirectories(out);var base=toAddr(0x91020000L);require(!currentProgram.getMemory().contains(base),"Classic VMX fixture collision");List<Fixture> fixtures=new ArrayList<>();int[][] regs={{13,13,0},{1,2,3},{31,7,31},{0,0,0}};for(String name:new String[]{"compareDot","compare","and","shift"})for(int[] x:regs)fixtures.add(new Fixture(name,name.equals("compareDot")?1158:name.equals("compare")?134:name.equals("and")?1028:644,x[0],x[1],x[2],name.equals("compareDot")));Random rng=new Random(0x469c1a551cL);int cases=0,failed=0,totalFallback=0;boolean stored=false;List<String> examples=new ArrayList<>();try{var block=currentProgram.getMemory().createInitializedBlock("private_classic_vmx_test",base,0x200,(byte)0,monitor,false);block.setExecute(true);for(int i=0;i<fixtures.size();i++){var f=fixtures.get(i);var a=base.add(i*8);int word=(4<<26)|(f.d<<21)|(f.a<<16)|(f.b<<11)|f.selector;currentProgram.getMemory().setBytes(a,ByteBuffer.allocate(8).putInt(word).putInt(0x4e800020).array());require(new DisassembleCommand(a,new AddressSet(a,a.add(3)),false).applyTo(currentProgram,monitor),"Classic VMX fixture decode");}
 for(int index=0;index<fixtures.size();index++){var f=fixtures.get(index);for(int trial=0;trial<128;trial++){var e=new EmulatorHelper(currentProgram);try{long[] gprs=new long[32];for(int n=0;n<32;n++){gprs[n]=rng.nextLong();e.writeRegister("r"+n,gprs[n]);}BigInteger[] vectors=new BigInteger[128];for(int n=0;n<128;n++){vectors[n]=new BigInteger(128,rng);e.writeRegister(n<32?"vs"+(32+n):"xv"+n,vectors[n]);}byte[] a=vb(vectors[f.a]),b=vb(vectors[f.b]);if(f.name.startsWith("compare")&&f.a!=f.b){for(int lane=0;lane<4;lane++){int value=ByteBuffer.wrap(a,lane*4,4).getInt();if(trial%4==0||trial%4==2){if(trial%4==2&&(lane&1)!=0)value^=1;ByteBuffer.wrap(b,lane*4,4).putInt(value);}else if(trial%4==1)ByteBuffer.wrap(b,lane*4,4).putInt(value^0x01010101);}vectors[f.b]=new BigInteger(1,b);e.writeRegister("vs"+(32+f.b),vectors[f.b]);}if(f.name.equals("shift")){int[] shifts={0,31,32,63,-1,0x80000000,1,16};for(int lane=0;lane<4;lane++)ByteBuffer.wrap(b,lane*4,4).putInt(shifts[(trial+lane)%shifts.length]);vectors[f.b]=new BigInteger(1,b);e.writeRegister("vs"+(32+f.b),vectors[f.b]);}a=vb(vectors[f.a]);b=vb(vectors[f.b]);byte[] want=operation(f.name.startsWith("compare")?"compare":f.name,a,b);int[] cr=new int[8];for(int n=0;n<8;n++){cr[n]=n==6?15:rng.nextInt(16);e.writeRegister("cr"+n,cr[n]);}int matches=0;for(int lane=0;lane<4;lane++)if(ByteBuffer.wrap(a,lane*4,4).getInt()==ByteBuffer.wrap(b,lane*4,4).getInt())matches++;int expectedCr=f.dot?(matches==4?8:matches==0?2:0):cr[6];long vscr=rng.nextInt()&0xffffffffL;e.writeRegister("xenonVSCR",vscr);long lr=rng.nextLong();e.writeRegister("LR",lr);e.writeRegister(e.getPCRegister(),base.getOffset()+index*8);baselineFallbacks(e);callbacks=0;boolean ok=e.step(monitor);String reason=ok?"":e.getLastError();if(ok&&!e.readRegister("vs"+(32+f.d)).equals(new BigInteger(1,want))){ok=false;reason="wrong vector result";}if(ok&&e.readRegister("cr6").intValue()!=expectedCr){ok=false;reason="CR6 expected"+expectedCr+" actual"+e.readRegister("cr6");}if(ok&&callbacks!=0){ok=false;reason="opaque CALLOTHER fallback required";}if(ok)for(int n=0;n<8;n++)if(n!=6&&e.readRegister("cr"+n).intValue()!=cr[n]){ok=false;reason="unrelated CR field changed";break;}if(ok)for(int n=0;n<32;n++)if(e.readRegister("r"+n).longValue()!=gprs[n]){ok=false;reason="GPR carrier changed";break;}if(ok)for(int n=0;n<128;n++)if(n!=f.d&&!e.readRegister(n<32?"vs"+(32+n):"xv"+n).equals(vectors[n])){ok=false;reason="unrelated vector changed";break;}if(ok&&(e.readRegister("xenonVSCR").longValue()!=vscr||e.readRegister("LR").longValue()!=lr||e.readRegister(e.getPCRegister()).longValue()!=base.getOffset()+index*8+4)){ok=false;reason="VSCR/LR/flow changed";}totalFallback+=callbacks;cases++;if(!ok){failed++;if(examples.size()<8)examples.add(f+" trial"+trial+" "+reason);}}finally{e.dispose();}}}
 var instruction=getInstructionAt(toAddr(0x800cc518L));if(instruction!=null){stored=instruction.getMnemonicString().equals("vcmpequw.");boolean crWrite=false;for(var op:instruction.getPcode()){if(op.getOpcode()==PcodeOp.CALLOTHER)stored=false;var o=op.getOutput();if(o!=null&&o.isRegister()&&o.getAddress().equals(currentProgram.getRegister("cr6").getAddress()))crWrite=true;}stored&=crWrite;}
 }finally{end(false);start();}boolean rolledBack=!currentProgram.getMemory().contains(base);Files.writeString(out.resolve("result.txt"),"cases="+cases+"\npassed="+(cases-failed)+"\nfailed="+failed+"\nopaque_fallbacks="+totalFallback+"\nstored_kernel_compare_cr6="+stored+"\nfixture_rollback="+rolledBack+"\nexamples="+examples+"\nOriginal classic words, four alias/register patterns, independent byte/word oracle, shift edge counts, all/none/mixed equality, complete GPR/vector/CR/VSCR/LR/PC preservation. Baseline fallbacks supply only opaque outputs and are forbidden for a PASS; they never set CR6. No firmware byte or saved instruction modification remains.\n");require(rolledBack,"Fixture rollback failed");require(failed==0&&cases==2048&&totalFallback==0&&stored,"CLASSIC VMX NATIVE REGRESSION: "+failed+"/"+cases+" failed; stored="+stored+"; "+examples);println("XENON CLASSIC VMX:2048 native cases and stored CR6 instruction PASS; fixtures rolled back");}
}
